<?php
/**
 * Standalone 1-Click Hostinger Auto-Deployer & Installer
 * Pokemon Calculator Hub
 * 
 * Usage:
 * 1. Upload this single file (deploy.php) to your Hostinger public_html/ folder.
 * 2. Open https://pokemoncalculator.site/deploy.php in your web browser.
 * 3. Enter your database credentials and click "Deploy Entire Site & Database".
 * 4. Done! All files, security .htaccess barriers, and database tables are installed.
 */

error_reporting(E_ALL);
ini_set('display_errors', '1');
set_time_limit(300);

$payload = '';

$deployed = false;
$msg = '';
$err = '';
$fileCount = 0;

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['do_deploy'])) {
    try {
        $dbHost = trim($_POST['db_host'] ?? 'localhost');
        $dbName = trim($_POST['db_name'] ?? '');
        $dbUser = trim($_POST['db_user'] ?? '');
        $dbPass = trim($_POST['db_pass'] ?? '');
        $appUrl = rtrim(trim($_POST['app_url'] ?? 'https://pokemoncalculator.site'), '/');

        // 1. Decompress & unpack files
        $rawJson = zlib_decode(base64_decode($payload));
        if (!$rawJson) {
            throw new Exception('Failed to decompress installation payload.');
        }

        $files = json_decode($rawJson, true);
        if (!is_array($files)) {
            throw new Exception('Invalid file dictionary payload.');
        }

        $targetDir = __DIR__;

        foreach ($files as $relPath => $b64Data) {
            $destPath = $targetDir . '/' . ltrim($relPath, '/');
            $parentDir = dirname($destPath);
            
            if (!is_dir($parentDir)) {
                mkdir($parentDir, 0755, true);
            }

            $content = base64_decode($b64Data);
            file_put_contents($destPath, $content);
            chmod($destPath, 0644);
            $fileCount++;
        }

        // Ensure proper folder permissions
        if (is_dir($targetDir . '/public/uploads')) {
            @chmod($targetDir . '/public/uploads', 0755);
        }

        // 2. Generate customized .env file
        if (!empty($dbName) && !empty($dbUser)) {
            $envContent = "# Production Environment\n" .
                "APP_ENV=production\n" .
                "APP_DEBUG=false\n" .
                "APP_URL=" . $appUrl . "\n\n" .
                "DB_HOST=" . $dbHost . "\n" .
                "DB_PORT=3306\n" .
                "DB_NAME=" . $dbName . "\n" .
                "DB_USER=" . $dbUser . "\n" .
                "DB_PASS=" . $dbPass . "\n" .
                "DB_CHARSET=utf8mb4\n";
            file_put_contents($targetDir . '/.env', $envContent);
            @chmod($targetDir . '/.env', 0644);

            // 3. Connect to Database & Import database.sql
            $dsn = "mysql:host=" . $dbHost . ";port=3306;dbname=" . $dbName . ";charset=utf8mb4";
            $pdo = new PDO($dsn, $dbUser, $dbPass, [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC
            ]);

            $sqlFile = $targetDir . '/database.sql';
            if (file_exists($sqlFile)) {
                $sql = file_get_contents($sqlFile);
                $sql = str_replace('http://localhost:8000', $appUrl, $sql);
                $sql = str_replace('https://pokemoncalculator.site', $appUrl, $sql);
                $pdo->exec($sql);
            }
        }

        $deployed = true;
        $msg = "Successfully installed " . $fileCount . " files, security .htaccess barriers, and database tables!";

    } catch (Exception $e) {
        $err = $e->getMessage();
    }
}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['delete_deployer'])) {
    @unlink(__FILE__);
    header('Location: /admin/login');
    exit;
}
?>
